<h2>Model renewal and price uplift</h2><p class="lead">Estimate renewed recurring revenue after retention, contractual price uplift and expansion.</p><div class="notice">Apply uplift only where contracts permit it. Expansion, downsell and churn should be modelled using definitions that match your recurring-revenue reporting.</div><div class="form-grid"><div class="field"><label for="base">Starting renewable ARR / contract value</label><input id="base" type="number" value="1000000" min="0" step="any"></div><div class="field"><label for="renew">Renewal / retained value (%)</label><input id="renew" type="number" value="90" min="0" max="100" step="any"></div><div class="field"><label for="uplift">Price uplift on renewed base (%)</label><input id="uplift" type="number" value="5" step="any"></div><div class="field"><label for="exp">Expansion on renewed base (%)</label><input id="exp" type="number" value="8" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Retained base</span><strong id="renewed">—</strong></div><div class="metric"><span>Price uplift value</span><strong id="upliftamt">—</strong></div><div class="metric"><span>Ending renewed + expansion value</span><strong id="ending">—</strong></div><div class="metric"><span>Net change vs starting base</span><strong id="growth">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('renewed').textContent='—';$('upliftamt').textContent='—';$('ending').textContent='—';$('growth').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const b=num('base'),rr=num('renew')/100,u=num('uplift')/100,e=num('exp')/100;if(!(b>=0&&rr>=0&&rr<=1&&Number.isFinite(u)&&Number.isFinite(e)&&u>-1&&e>-1))throw 0;const ret=b*rr,up=ret*u,end=ret*(1+u)+ret*e;$('renewed').textContent=fmt(ret,2);$('upliftamt').textContent=fmt(up,2);$('ending').textContent=fmt(end,2);$('growth').textContent=b>0?fmt((end/b-1)*100,2)+'%':'—';$('note').textContent='This separates retained base, price uplift and expansion. It is a planning model, not a substitute for contract-level renewal forecasting.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
